import React, { useCallback, useState } from 'react';
import { LiveboardEmbed } from '@thoughtspot/visual-embed-sdk/react';
import { RuntimeFilterOp } from '@thoughtspot/visual-embed-sdk';
import { THOUGHTSPOT_LIVEBOARD_ID, TOP_HEADER_PX } from '../config/thoughtspot';
import { useTier } from '../config/TierContext';
import { formatThoughtSpotEmbedError } from '../utils/thoughtspotErrors';

const BST_BLUE = '#1D3FA8';
const CHIP_BG = '#eef1fb';
const CHIP_COLOR = BST_BLUE;
const CHIP_ACTIVE_BG = BST_BLUE;
const CHIP_ACTIVE_COLOR = '#ffffff';
const EMBED_MIN_H = `calc(100vh - ${TOP_HEADER_PX}px - 200px)`;

// ─── Date period helpers ──────────────────────────────────────────────────────

interface DatePeriod { id: string; label: string; startDate: () => string; }

const DATE_PERIODS: DatePeriod[] = [
  { id: '30d', label: 'Last 30 Days',   startDate: () => daysAgo(30) },
  { id: '3m',  label: 'Last 3 Months',  startDate: () => monthsAgo(3) },
  { id: '12m', label: 'Last 12 Months', startDate: () => monthsAgo(12) },
  { id: 'ytd', label: 'Year to Date',   startDate: () => `${new Date().getFullYear()}-01-01` },
];

function daysAgo(n: number)  { const d = new Date(); d.setDate(d.getDate() - n);     return d.toISOString().split('T')[0]; }
function monthsAgo(n: number){ const d = new Date(); d.setMonth(d.getMonth() - n);   return d.toISOString().split('T')[0]; }

// ─── Dimension filters ────────────────────────────────────────────────────────
// Add values matching your ThoughtSpot column data to enable selection chips.

interface DimGroup { column: string; label: string; values: string[]; }

const DIM_GROUPS: DimGroup[] = [
  { column: 'Plant',    label: 'Plant',    values: [] },
  { column: 'Driver',   label: 'Driver',   values: [] },
  { column: 'Vehicle',  label: 'Vehicle',  values: [] },
  { column: 'Customer', label: 'Customer', values: [] },
];

// ─── Chip ─────────────────────────────────────────────────────────────────────

function Chip({ label, active, onClick }: { label: string; active: boolean; onClick: () => void }) {
  return (
    <button
      type="button"
      onClick={onClick}
      style={{
        padding: '5px 14px',
        borderRadius: 20,
        border: `1px solid ${active ? BST_BLUE : '#d0d8f0'}`,
        background: active ? CHIP_ACTIVE_BG : CHIP_BG,
        color: active ? CHIP_ACTIVE_COLOR : CHIP_COLOR,
        fontSize: 13,
        fontWeight: active ? 700 : 500,
        cursor: 'pointer',
        whiteSpace: 'nowrap',
        lineHeight: '1.4',
        transition: 'all 0.12s ease',
      }}
    >
      {label}
    </button>
  );
}

// ─── Divider between filter groups ───────────────────────────────────────────

function Sep() {
  return <span style={{ color: '#c8d0e8', fontSize: 18, lineHeight: '1', alignSelf: 'center', userSelect: 'none' }}>|</span>;
}

// ─── Page ─────────────────────────────────────────────────────────────────────

interface Props { title: string; description?: string; tabId: string; }

export default function LiveboardTabPage({ title, description, tabId }: Props) {
  const { hiddenActions, disabledActions } = useTier();

  const [datePeriod, setDatePeriod]   = useState('12m');
  const [selected, setSelected]       = useState<Record<string, string[]>>({});

  const toggle = (col: string, val: string) =>
    setSelected(prev => {
      const cur = prev[col] ?? [];
      return { ...prev, [col]: cur.includes(val) ? cur.filter(v => v !== val) : [...cur, val] };
    });

  const clearAll  = () => { setDatePeriod('12m'); setSelected({}); };
  const hasActive = datePeriod !== '12m' || Object.values(selected).some(v => v.length > 0);

  const period = DATE_PERIODS.find(p => p.id === datePeriod)!;

  const runtimeFilters = [
    { columnName: 'Date', operator: RuntimeFilterOp.GE, values: [period.startDate()] },
    ...DIM_GROUPS
      .filter(g => (selected[g.column] ?? []).length > 0)
      .map(g => ({ columnName: g.column, operator: RuntimeFilterOp.IN, values: selected[g.column] })),
  ];

  const embedKey = `${tabId}|${datePeriod}|${JSON.stringify(selected)}`;

  const onError = useCallback((err: { data?: { errorMessage?: string }; message?: string }) => {
    console.error(`[ThoughtSpot – ${title}]`, formatThoughtSpotEmbedError(err), err);
  }, [title]);

  return (
    <div style={{ backgroundColor: BST_BLUE, minHeight: `calc(100vh - ${TOP_HEADER_PX}px)` }}>

      {/* Blue page header */}
      <div style={{ padding: '1.75rem 2.5rem 1.25rem' }}>
        <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: '0.1em', textTransform: 'uppercase', color: 'rgba(255,255,255,0.5)', marginBottom: 6 }}>
          BST Media
        </div>
        <h1 style={{ fontSize: 26, fontWeight: 800, color: '#ffffff', margin: 0 }}>{title}</h1>
        {description && (
          <p style={{ fontSize: 14, color: 'rgba(255,255,255,0.7)', margin: '4px 0 0', maxWidth: 600 }}>
            {description}
          </p>
        )}
      </div>

      {/* White embed card */}
      <div style={{ padding: '0 2.5rem 2rem' }}>
        <div style={{ backgroundColor: '#ffffff', borderRadius: 12, overflow: 'hidden' }}>

          {/* ── Native filter bar (top of white card) ── */}
          <div style={{
            padding: '12px 20px',
            borderBottom: '1px solid #eef0f8',
            display: 'flex',
            alignItems: 'center',
            gap: 6,
            flexWrap: 'wrap',
          }}>
            {/* Date chips */}
            {DATE_PERIODS.map(p => (
              <Chip
                key={p.id}
                label={p.id === datePeriod
                  ? `Date: ${p.label}`
                  : p.label}
                active={datePeriod === p.id}
                onClick={() => setDatePeriod(p.id)}
              />
            ))}

            {/* Dimension chip groups */}
            {DIM_GROUPS.map(group => {
              const activeVals = selected[group.column] ?? [];
              const isAll = activeVals.length === 0;
              if (group.values.length === 0) {
                // No values configured yet — show placeholder chip
                return (
                  <React.Fragment key={group.column}>
                    <Sep />
                    <Chip
                      label={`${group.label}: All`}
                      active={false}
                      onClick={() => {}}
                    />
                  </React.Fragment>
                );
              }
              return (
                <React.Fragment key={group.column}>
                  <Sep />
                  <Chip
                    label={`${group.label}: All`}
                    active={isAll}
                    onClick={() => setSelected(prev => ({ ...prev, [group.column]: [] }))}
                  />
                  {group.values.map(val => (
                    <Chip
                      key={val}
                      label={val}
                      active={activeVals.includes(val)}
                      onClick={() => toggle(group.column, val)}
                    />
                  ))}
                </React.Fragment>
              );
            })}

            {/* Reset button */}
            {hasActive && (
              <>
                <Sep />
                <button
                  type="button"
                  onClick={clearAll}
                  style={{
                    padding: '5px 12px',
                    borderRadius: 20,
                    border: '1px solid #f0c0c0',
                    background: '#fff5f5',
                    color: '#c0392b',
                    fontSize: 12,
                    fontWeight: 600,
                    cursor: 'pointer',
                    whiteSpace: 'nowrap',
                  }}
                >
                  Reset
                </button>
              </>
            )}
          </div>

          {/* ThoughtSpot liveboard — native header hidden */}
          <LiveboardEmbed
            key={embedKey}
            liveboardId={THOUGHTSPOT_LIVEBOARD_ID}
            activeTabId={tabId}
            fullHeight
            hideLiveboardHeader
            hiddenActions={hiddenActions}
            disabledActions={disabledActions}
            runtimeFilters={runtimeFilters}
            isLiveboardStylingAndGroupingEnabled
            additionalFlags={{ enable2ColumnLayout: true }}
            onError={onError}
            style={{ width: '100%', minHeight: EMBED_MIN_H, display: 'block', border: 'none' }}
          />
        </div>
      </div>
    </div>
  );
}
